import sys
sys.path.insert(0,'/tmp')
from run_tests import *
import subprocess, pathlib, os, shutil

def git(repo,*a,env_extra=None):
    env=os.environ.copy()
    if env_extra: env.update(env_extra)
    return subprocess.run(["git"]+list(a),cwd=repo,check=True,capture_output=True,text=True,env=env)

def build(path, specs):
    # specs: list of functions to apply after 3 commits with known dates
    if os.path.exists(path): shutil.rmtree(path)
    os.makedirs(path)
    git(path,"init","-q"); git(path,"config","user.email","a@a.com"); git(path,"config","user.name","A")
    pathlib.Path(path,".clog.toml").write_text('[clog]\n[sections]\nFeatures=["feat"]\n')
    dates=["2020-01-01T00:00:00+00:00","2021-01-01T00:00:00+00:00","2022-01-01T00:00:00+00:00","2026-01-01T00:00:00+00:00","2026-06-01T00:00:00+00:00"]
    for i,msg in enumerate(["feat: c1","feat: c2","feat: c3"]):
        p=pathlib.Path(path,"f.txt"); p.write_text(str(i))
        git(path,"add","-A"); git(path,"commit","-qm",msg,env_extra={"GIT_AUTHOR_DATE":dates[i],"GIT_COMMITTER_DATE":dates[i]})
    for s in specs: s(path)
    for i,msg in enumerate(["feat: c4","feat: c5"]):
        p=pathlib.Path(path,"f.txt"); p.write_text(str(10+i))
        git(path,"add","-A"); git(path,"commit","-qm",msg,env_extra={"GIT_AUTHOR_DATE":dates[3+i],"GIT_COMMITTER_DATE":dates[3+i]})
    return path

def ann(name,rev,tagdate):
    def f(repo):
        git(repo,"tag","-a",name,"-m","msg",rev,env_extra={"GIT_COMMITTER_DATE":tagdate})
    return f
def light(name,rev):
    def f(repo): git(repo,"tag",name,rev)
    return f

def showcase(label,specs):
    repo=build(f"/tmp/lt6_{label}",specs)
    r=run(repo,["-F"])
    lines=[l for l in r.stdout.splitlines() if l.startswith("*")]
    print(label,"->", lines)
    print(git(repo,"for-each-ref","refs/tags","--format=%(refname:short) creatordate=%(creatordate:iso) tagger=%(taggerdate:iso) *creatordate=%(*creatordate:iso)").stdout)

