    #[arg(short = 'F', long = "from-latest-tag", help = "use latest tag as start (instead of --from)")]
    from_latest_tag: bool,

    #[arg(short = 'l', long = "link-style", value_name = "STR", default_value = "github", help = "The style of repository link to generate")]
    link_style: LinkStyle,

    #[arg(short = 'C', long = "changelog", value_name = "PATH", help = "A previous changelog to prepend new changes to (this is like using the same file for both --infile and --outfile and should not be used in conjunction with either)", conflicts_with_all = ["infile", "outfile"])]
    changelog: Option<String>,
}

// ---------- Config ----------
#[derive(Debug, Clone, PartialEq, Eq)]
enum ConfigLinkStyle { Github, Gitlab, Stash, Cgit }
impl<'de> Deserialize<'de> for ConfigLinkStyle {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error> where D: serde::Deserializer<'de> {
        let s = String::deserialize(deserializer)?;
        match s.to_lowercase().as_str() {
            "github" => Ok(Self::Github),
            "gitlab" => Ok(Self::Gitlab),
            "stash" => Ok(Self::Stash),
            "cgit" => Ok(Self::Cgit),
            _ => Err(de::Error::custom("invalid link-style")),
        }
    }
}
#[derive(Debug, Clone, PartialEq, Eq)]
enum ConfigOutputFormat { Markdown, Json }
impl<'de> Deserialize<'de> for ConfigOutputFormat {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error> where D: serde::Deserializer<'de> {
        let s = String::deserialize(deserializer)?;
        match s.to_lowercase().as_str() {
            "markdown" => Ok(Self::Markdown),
            "json" => Ok(Self::Json),
            _ => Err(de::Error::custom("invalid output-format")),
        }
    }
}

#[derive(Debug, Default, Deserialize)]
struct ClogSection {
    #[serde(default)]
    repository: Option<String>,
    #[serde(default)]
    subtitle: Option<String>,
    #[serde(default, rename = "link-style")]
    link_style: Option<ConfigLinkStyle>,
    #[serde(default, rename = "output-format")]
    output_format: Option<ConfigOutputFormat>,
    #[serde(default, rename = "from-latest-tag")]
    from_latest_tag: Option<bool>,
    #[serde(default)]
    outfile: Option<String>,
    #[serde(default)]
    infile: Option<String>,
    #[serde(default)]
    changelog: Option<String>,
    #[serde(default, rename = "git-dir")]
    git_dir: Option<String>,
}

#[derive(Debug)]
struct Sections(Vec<(String, Vec<String>)>);
impl Default for Sections { fn default() -> Self { Sections(Vec::new()) } }
impl<'de> Deserialize<'de> for Sections {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error> where D: serde::Deserializer<'de> {
        struct V;
        impl<'de> Visitor<'de> for V {
            type Value = Sections;
            fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result { write!(f, "a table of sections") }
            fn visit_map<A>(self, mut map: A) -> Result<Sections, A::Error> where A: MapAccess<'de> {
                let mut vec = Vec::new();
                while let Some((k, v)) = map.next_entry::<String, Vec<String>>()? {
                    vec.push((k, v));
                }
                Ok(Sections(vec))
            }
        }
        deserializer.deserialize_map(V)
    }
}

#[derive(Debug, Deserialize)]
struct ConfigFile {
    clog: ClogSection,
    #[serde(default)]
    sections: Option<Sections>,
}

// ---------- Data ----------
#[derive(Debug, Clone)]
struct Iss {
    issue: String,
    issue_link: String,
}
#[derive(Debug, Clone)]
struct Commit {
    component: Option<String>,
    subject: String,
    hash: String, // full
    commit_link: String,
    closes: Option<Vec<Iss>>,
    breaks: Option<Vec<Iss>>,
}
#[derive(Debug, Clone)]
struct SectionOut {
    title: String,
    // groups in sorted component order
    groups: Vec<(String, Vec<Commit>)>, // key "" for none
    commits_flat: Vec<Commit>,
}

#[derive(Debug)]
enum AppError {
    Io,
    ParseToml,
    SemVer,
}
impl AppError {
    fn msg(&self) -> &'static str {
        match self {
            AppError::Io => "fatal I/O error with output file",
            AppError::ParseToml => "Failed to parse TOML configuration file",
            AppError::SemVer => "Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.",
        }
    }
}

fn print_error(e: &AppError) {
    eprintln!("\x1b[1;31merror:\x1b[0m {}", e.msg());
}

fn utc_today() -> String {
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0) as i64;
    let days = secs.div_euclid(86400);
    // civil from days (Howard Hinnant algorithm)
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097; // [0, 146096]
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100); // [0, 365]
    let mp = (5*doy + 2)/153; // [0, 11]
    let d = doy - (153*mp+2)/5 + 1; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // [1,12]
    let year = if m <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}", year, m, d)
}

fn absolutize(p: &Path, cwd: &Path) -> PathBuf {
    if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) }
}

fn git_base_args(git_dir: &Path, work_tree: &Path) -> Vec<String> {
    vec![
        format!("--git-dir={}", git_dir.display()),
        format!("--work-tree={}", work_tree.display()),
    ]
}

fn main() {
    std::process::exit(run());
}

fn run() -> i32 {
    let start = Instant::now();
    let args = Args::parse();

    // config read
    let config_content = match fs::read_to_string(&args.config) {
        Ok(c) => c,
        Err(_) => { print_error(&AppError::Io); return 1; }
    };
    let cfg: ConfigFile = match toml::from_str(&config_content) {
        Ok(c) => c,
        Err(_) => { print_error(&AppError::ParseToml); return 1; }
    };
    let sections_cfg: Vec<(String, Vec<String>)> = cfg.sections.map(|s| s.0).unwrap_or_default();
    let cfg_from_latest_tag = cfg.clog.from_latest_tag.unwrap_or(false);

    // git dir / work tree resolution
    let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let config_path = PathBuf::from(&args.config);
    let config_abs = absolutize(&config_path, &cwd);
    let config_parent = config_abs.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from(""));

    let (git_dir, work_tree) = if let Some(g) = &args.git_dir {
        let gd = absolutize(Path::new(g), &cwd);
        let wt = if let Some(w) = &args.work_tree {
            absolutize(Path::new(w), &cwd)
        } else {
            gd.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from(""))
        };
        (gd, wt)
    } else {
        (config_parent.join(".git"), config_parent.clone())
    };

    // effective infile / outfile
    let mut infile: Option<String> = None;
    let mut outfile: Option<String> = None;
    if let Some(v) = cfg.clog.infile.clone() { infile = Some(v); }
    if let Some(v) = cfg.clog.outfile.clone() { outfile = Some(v); }
    if let Some(v) = cfg.clog.changelog.clone() { infile = Some(v.clone()); outfile = Some(v); }
    // CLI
    if let Some(v) = args.infile.clone() { infile = Some(v); }
    if let Some(v) = args.outfile.clone() { outfile = Some(v); }
    if let Some(v) = args.changelog.clone() { infile = Some(v.clone()); outfile = Some(v); }

    // version determination
    let version: Option<String>;
    let patch_version = false;
    if let Some(v) = &args.setversion {
        version = Some(v.clone());
    } else if args.major || args.minor || args.patch {
        // Call git describe (used by the original for the previous version).
        // If spawning fails, the original panics.
        let mut cmd = Command::new("git");
        cmd.args(git_base_args(&git_dir, &work_tree));
        cmd.arg("describe");
        match cmd.output() {
            Ok(_) => {
                print_error(&AppError::SemVer);
                return 1;
            }
            Err(e) => {
                // Emulate panic output of the original library
                let pid = std::process::id();
                eprintln!("\nthread 'main' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clog-0.11.0/src/clog.rs:654:33:\nFailed to run 'git describe' with error: {}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", pid, e);
                return 101;
            }
        }
    } else {
        version = None;
    }

    // range determination
    let range_arg: String;
    if let Some(from) = &args.from {
        range_arg = format!("{}..{}", from, args.to);
    } else if args.from_latest_tag {
        // latest tag: rev-list --tags --max-count=1
        let mut cmd = Command::new("git");
        cmd.args(git_base_args(&git_dir, &work_tree));
        cmd.args(["rev-list", "--tags", "--max-count=1"]);
        let out = match cmd.output() {
            Ok(o) => o,
            Err(_) => { print_error(&AppError::Io); return 1; }
        };
        let hash = String::from_utf8_lossy(&out.stdout).trim().to_string();
        range_arg = format!("{}..{}", hash, args.to);
    } else if cfg_from_latest_tag {
        range_arg = format!("..{}", args.to);
    } else {
        range_arg = "HEAD".to_string();
    }

    // git log
    let mut cmd = Command::new("git");
    cmd.args(git_base_args(&git_dir, &work_tree));
    cmd.arg("log");
    cmd.arg("-E");
    // The original builds a grep pattern with empty alternatives (matching all);
    // omit grep so parser is authoritative.
    cmd.arg("--format=%H%n%s%n%b%n==END==");
    cmd.arg(&range_arg);
    let git_out = match cmd.output() {
        Ok(o) => o,
        Err(_) => { print_error(&AppError::Io); return 1; }
    };
    let git_text = String::from_utf8_lossy(&git_out.stdout).into_owned();

    // parse commits
    // Build section accumulators in config order
    struct Acc { title: String, aliases: Vec<String>, commits: Vec<Commit> }
    let mut accs: Vec<Acc> = sections_cfg.iter().map(|(t, a)| Acc { title: t.clone(), aliases: a.clone(), commits: Vec::new() }).collect();

    for piece in git_text.split("==END==") {
        let trimmed = piece.trim();
        if trimmed.is_empty() { continue; }
        let mut lines = trimmed.lines();
        let hash = match lines.next() { Some(h) => h.to_string(), None => continue };
        let subject_line = match lines.next() { Some(s) => s.to_string(), None => continue };
        let body_lines: Vec<String> = lines.map(|s| s.to_string()).collect();

        if let Some((typ, component, subject)) = parse_subject(&subject_line) {
            // find section
            let mut sec_idx: Option<usize> = None;
            for (i, acc) in accs.iter().enumerate() {
                if acc.aliases.iter().any(|a| a == &typ) { sec_idx = Some(i); break; }
            }
            if let Some(idx) = sec_idx {
                let commit = build_commit(hash, component, subject, &body_lines, &args);
                accs[idx].commits.push(commit);
            }
        }
    }

    // build output sections (filter empty, group by component)
    let mut sections_out: Vec<SectionOut> = Vec::new();
    for acc in accs {
        if acc.commits.is_empty() { continue; }
        let mut groups_map: BTreeMap<String, Vec<Commit>> = BTreeMap::new();
        for c in acc.commits {
            let key = c.component.clone().unwrap_or_default();
            groups_map.entry(key).or_default().push(c);
        }
        let mut commits_flat: Vec<Commit> = Vec::new();
        let mut groups: Vec<(String, Vec<Commit>)> = Vec::new();
        for (k, v) in groups_map {
            for c in &v { commits_flat.push(c.clone()); }
            groups.push((k, v));
        }
        sections_out.push(SectionOut { title: acc.title, groups, commits_flat });
    }

    let date = utc_today();
    let generated = match args.format {
        OutputFormat::Markdown => gen_markdown(&version, patch_version, &args.subtitle, &date, &sections_out),
        OutputFormat::Json => gen_json(&version, patch_version, &args.subtitle, &date, &sections_out),
    };

    // previous content
    let has_prev_source = infile.is_some() || outfile.is_some();
    let previous: String = if let Some(in_path) = &infile {
        fs::read_to_string(in_path).unwrap_or_default()
    } else if let Some(out_path) = &outfile {
        fs::read_to_string(out_path).unwrap_or_default()
    } else {
        String::new()
    };
    let full_output = if has_prev_source {
        format!("{}\n\n\n{}", generated, previous)
    } else {
        generated
    };

    if let Some(out_path) = &outfile {
        if fs::write(out_path, &full_output).is_err() {
            print_error(&AppError::Io);
            return 1;
        }
    } else {
        // print to stdout without extra newline
        let stdout = io::stdout();
        let mut handle = stdout.lock();
        let _ = handle.write_all(full_output.as_bytes());
        let _ = handle.flush();
    }
    println!("changelog written. (took {} ms)", start.elapsed().as_millis());
    0
}

fn parse_subject(line: &str) -> Option<(String, Option<String>, String)> {
    // Determine if a component is present: '(' before any ':' in the prefix,
    // or '(' with no ':' before it (colon may be inside component)
    let bytes = line.as_bytes();
    // find first '('
    if let Some(paren_idx) = line.find('(') {
        let before_paren = &line[..paren_idx];
        if !before_paren.contains(':') {
            // component attempt
            let after_paren = &line[paren_idx + 1..];
            if let Some(close_idx_rel) = after_paren.find(')') {
                let close_idx = paren_idx + 1 + close_idx_rel;
                // char after close must be ':'
                if line[close_idx + 1..].starts_with(':') {
                    let typ = before_paren.to_string();
                    if typ.is_empty() { return None; }
                    let comp_str = &line[paren_idx + 1..close_idx];
                    let component = if comp_str.is_empty() { None } else { Some(comp_str.to_string()) };
                    let subject = line[close_idx + 2..].to_string();
                    return Some((typ, component, subject));
                } else {
                    return None;
                }
            } else {
                return None;
            }
        }
    }
    // no component
    let colon_idx = line.find(':')?;
    let typ = &line[..colon_idx];
    if typ.is_empty() { return None; }
    if typ.contains('(') { return None; }
    let subject = line[colon_idx + 1..].to_string();
    Some((typ.to_string(), None, subject))
}

fn build_commit(hash: String, component: Option<String>, subject: String, body_lines: &[String], args: &Args) -> Commit {
    // commit link
    let commit_link = match &args.repository {
        None => hash.chars().take(8).collect::<String>(),
        Some(repo) => match args.link_style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{}/commit/{}", repo, hash),
            LinkStyle::Stash => format!("{}/commits/{}", repo, hash),
            LinkStyle::Cgit => format!("{}/commit/?id={}", repo, hash),
        },
    };
    let mut closes_vec: Vec<Iss> = Vec::new();
    let mut breaks_vec: Vec<Iss> = Vec::new();
    for line in body_lines {
        if let Some(iss) = parse_closes_line(line, args) { closes_vec.push(iss); }
        if let Some(iss) = parse_breaks_line(line, args) { breaks_vec.push(iss); }
    }
    Commit {
        component,
        subject,
        hash,
        commit_link,
        closes: if closes_vec.is_empty() { None } else { Some(closes_vec) },
        breaks: if breaks_vec.is_empty() { None } else { Some(breaks_vec) },
    }
}

fn make_issue_link(issue: &str, args: &Args) -> String {
    match &args.repository {
        None => issue.to_string(),
        Some(repo) => match args.link_style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{}/issues/{}", repo, issue),
            LinkStyle::Stash | LinkStyle::Cgit => issue.to_string(),
        },
    }
}

// Find pattern: keyword + " #" + digits, with repeated ",\s#digits" extensions.
// Returns last digits in the extension chain.
fn find_keyword_issue(line: &str, keywords: &[&str]) -> Option<String> {
    let mut best: Option<(usize, String, usize)> = None; // (start_idx, issue, end_index-after-digits-chain)
    for kw in keywords {
        let mut search_from = 0usize;
        while let Some(rel) = line[search_from..].find(kw) {
            let start = search_from + rel;
            let after_kw = start + kw.len();
            // require " #"
            if line[after_kw..].starts_with(" #") {
                let digits_start = after_kw + 2;
                let mut digits_end = digits_start;
                for ch in line[digits_start..].chars() {
                    if ch.is_ascii_digit() { digits_end += ch.len_utf8(); } else { break; }
                }
                if digits_end > digits_start {
                    let mut issue = line[digits_start..digits_end].to_string();
                    let mut pos = digits_end;
                    // repeated ",\s#digits"
                    loop {
                        let rest = &line[pos..];
                        let mut chars = rest.chars();
                        if let Some(',') = chars.next() {
                            // one whitespace
                            let after_comma = &rest[1..];
                            let mut ws_chars = after_comma.chars();
                            if let Some(ws) = ws_chars.next() {
                                if ws.is_whitespace() && ws != '\n' {
                                    let after_ws = &after_comma[ws.len_utf8()..];
                                    if after_ws.starts_with('#') {
                                        let dstart = 1;
                                        let mut dend = dstart;
                                        for ch in after_ws[dstart..].chars() {
                                            if ch.is_ascii_digit() { dend += ch.len_utf8(); } else { break; }
                                        }
                                        if dend > dstart {
                                            issue = after_ws[dstart..dend].to_string();
                                            pos = pos + 1 + ws.len_utf8() + dend;
                                            continue;
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    }
                    // record if earliest
                    if best.as_ref().map(|(s, _, _)| start < *s).unwrap_or(true) {
                        best = Some((start, issue, pos));
                    }
                    // move search_from beyond this keyword occurrence to find other candidates? we keep earliest, break
                    break;
                }
            }
            search_from = after_kw;
            if search_from >= line.len() { break; }
        }
    }
    best.map(|(_, issue, _)| issue)
}

fn parse_closes_line(line: &str, args: &Args) -> Option<Iss> {
    let issue = find_keyword_issue(line, &["Closes", "Fixes", "Resolves"])?;
    Some(Iss { issue_link: make_issue_link(&issue, args), issue })
}
fn parse_breaks_line(line: &str, args: &Args) -> Option<Iss> {
    if let Some(issue) = find_keyword_issue(line, &["Breaks"]) {
        return Some(Iss { issue_link: make_issue_link(&issue, args), issue });
    }
    if line.to_lowercase().contains("breaking") {
        let issue = String::new();
        return Some(Iss { issue_link: make_issue_link(&issue, args), issue });
    }
    None
}

fn iss_suffix(vec_opt: &Option<Vec<Iss>>, label: &str) -> String {
    if let Some(v) = vec_opt {
        let parts: Vec<String> = v.iter().map(|i| format!("[#{}]({})", i.issue, i.issue_link)).collect();
        format!(", {} {}", label, parts.join(", "))
    } else {
        String::new()
    }
}

fn gen_markdown(version: &Option<String>, patch_version: bool, subtitle: &Option<String>, date: &str, sections: &[SectionOut]) -> String {
    let v = version.as_deref().unwrap_or("");
    let sub = subtitle.as_deref().unwrap_or("");
    let hashes = if patch_version { "###" } else { "##" };
    let mut s = format!("<a name=\"{}\"></a>\n{} {} {} ({})\n\n", v, hashes, v, sub, date);
    for sec in sections {
        s.push_str(&format!("\n#### {}\n\n", sec.title));
        for (comp_key, commits) in &sec.groups {
            if comp_key.is_empty() {
                for c in commits {
                    let inner = format!("[{}]({}){}{}", short_hash(&c.hash), c.commit_link, iss_suffix(&c.closes, "closes"), iss_suffix(&c.breaks, "breaks"));
                    s.push_str(&format!("*  {} ({})\n", c.subject, inner));
                }
            } else if commits.len() == 1 {
                let c = &commits[0];
                let inner = format!("[{}]({}){}{}", short_hash(&c.hash), c.commit_link, iss_suffix(&c.closes, "closes"), iss_suffix(&c.breaks, "breaks"));
                s.push_str(&format!("* **{}:** {} ({})\n", comp_key, c.subject, inner));
            } else {
                s.push_str(&format!("* **{}:**\n", comp_key));
                for c in commits {
                    let inner = format!("[{}]({}){}{}", short_hash(&c.hash), c.commit_link, iss_suffix(&c.closes, "closes"), iss_suffix(&c.breaks, "breaks"));
                    s.push_str(&format!("  * {} ({})\n", c.subject, inner));
                }
            }
        }
    }
    s
}

fn short_hash(h: &str) -> String { h.chars().take(8).collect() }

fn iss_vec_json(v: &[Iss]) -> String {
    let parts: Vec<String> = v.iter().map(|i| format!("{{\"issue\":{},\"issue_link\":{}}}", i.issue, serde_json::to_string(&i.issue_link).unwrap())).collect();
    format!("[{}]", parts.join(","))
}

fn gen_json(version: &Option<String>, patch_version: bool, subtitle: &Option<String>, date: &str, sections: &[SectionOut]) -> String {
    let sections_json = if sections.is_empty() {
        "null".to_string()
    } else {
        let sec_parts: Vec<String> = sections.iter().map(|sec| {
            let commit_parts: Vec<String> = sec.commits_flat.iter().map(|c| {
                let comp = match &c.component { None => "null".to_string(), Some(x) => serde_json::to_string(x).unwrap() };
                let closes = match &c.closes { None => "null".to_string(), Some(v) => iss_vec_json(v) };
                let breaks = match &c.breaks {
                    None => "null".to_string(),
                    Some(_) => match &c.closes { None => "[]".to_string(), Some(v) => iss_vec_json(v) },
                };
                format!("{{\"component\":{},\"subject\":{},\"commit_link\":{},\"closes\":{},\"breaks\":{}}}", comp, serde_json::to_string(&c.subject).unwrap(), serde_json::to_string(&c.commit_link).unwrap(), closes, breaks)
            }).collect();
            format!("{{\"title\":{},\"commits\":[{}]}}", serde_json::to_string(&sec.title).unwrap(), commit_parts.join(","))
        }).collect();
        format!("[{}]", sec_parts.join(","))
    };
    let subtitle_str = subtitle.as_deref().unwrap_or("null");
    format!("{{\"header\":{{\"version\":{:?},\"patch_version\":{},\"subtitle\":{},\"date\":\"{}\"}},\"sections\":{}}}", version, patch_version, subtitle_str, date, sections_json)
}
RS"}

