fn normalize_toml_key(raw: &str) -> Option<String> {
    let k = raw.trim();
    if k.is_empty() { return None; }
    // dotted keys are too complex for the fallback
    // check for a dot outside quotes
    let mut in_s = false;
    let mut in_d = false;
    for ch in k.chars() {
        match ch {
            '\'' if !in_d => in_s = !in_s,
            '"' if !in_s => in_d = !in_d,
            '.' if !in_s && !in_d => return None,
            _ => {}
        }
