    let mut delete: Vec<bool> = vec![false; lines.len()];
    let mut seen: std::collections::HashMap<(String, String), usize> = std::collections::HashMap::new();
    let mut seen_tables: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut current_table = String::new(); // "" = root
    let mut bracket_depth: i32 = 0;
    let mut in_multiline_value = false;

    for (i, raw_line) in lines.iter().enumerate() {
        let line = raw_line.trim();
        if in_multiline_value {
