        if let Some(&prev) = seen.get(&id) {
            if prev >= usize::MAX - lines.len() {
                return None; // duplicate of a multi-line assignment
            }
            // classify tolerance
            let tolerant = if current_table.is_empty() {
                key != "clog" && key != "sections"
            } else if current_table == "clog" {
                !known_clog.contains(&key.as_str())
            } else if current_table == "sections" {
                true
            } else if current_table.starts_with("sections") {
                return None;
            } else {
                true
            };
            if !tolerant {
                return None;
            }
