fn find_unquoted_equals(line: &str) -> Option<usize> {
    let mut in_s = false;
    let mut in_d = false;
    let mut escaped = false;
    for (idx, ch) in line.char_indices() {
        if in_d {
            if escaped { escaped = false; continue; }
            if ch == '\\' { escaped = true; continue; }
            if ch == '"' { in_d = false; }
            continue;
        }
        if in_s {
            if ch == '\'' { in_s = false; }
            continue;
        }
        match ch {
            '"' => in_d = true,
            '\'' => in_s = true,
            '=' => return Some(idx),
            '#' => return None,
            _ => {}
        }
    }
    None
}

fn bracket_delta(s: &str) -> i32 {
    let mut depth = 0i32;
    let mut in_s = false;
    let mut in_d = false;
    let mut escaped = false;
    for ch in s.chars() {
        if in_d {
            if escaped { escaped = false; continue; }
            if ch == '\\' { escaped = true; continue; }
            if ch == '"' { in_d = false; }
            continue;
        }
        if in_s {
            if ch == '\'' { in_s = false; }
            continue;
        }
        match ch {
            '"' => in_d = true,
            '\'' => in_s = true,
            '[' | '{' => depth += 1,
            ']' | '}' => depth -= 1,
            '#' => break,
            _ => {}
        }
    }
    depth
}

