fn normalize_toml_key(raw: &str) -> Option<String> {
    let k = raw.trim();
    if k.is_empty() { return None; }
    let mut in_s = false;
    let mut in_d = false;
    for ch in k.chars() {
        match ch {
            '\'' if !in_d => in_s = !in_s,
            '"' if !in_s => in_d = !in_d,
            '.' if !in_s && !in_d => return None,
            _ => {}
        }
    }
    if k.len() >= 2 && ((k.starts_with('"') && k.ends_with('"')) || (k.starts_with('\'') && k.ends_with('\''))) {
        Some(k[1..k.len()-1].to_string())
    } else if k.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
        Some(k.to_string())
    } else {
        None
    }
}

fn config_from_str_legacy(content: &str) -> Option<ConfigFile> {
    let triple_d = "\"\"\"";
    let triple_s = "'''";
    if content.contains(triple_d) || content.contains(triple_s) {
        return None;
    }
    let known_clog: [&str; 9] = ["repository", "subtitle", "link-style", "output-format", "from-latest-tag", "outfile", "infile", "changelog", "git-dir"];
    let lines: Vec<&str> = content.lines().collect();
    let mut delete: Vec<bool> = vec![false; lines.len()];
    let mut seen: std::collections::HashMap<(String, String), usize> = std::collections::HashMap::new();
    let mut seen_tables: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut current_table = String::new();
    let mut bracket_depth: i32 = 0;
    let mut in_multiline_value = false;

    for (i, raw_line) in lines.iter().enumerate() {
        let line = raw_line.trim();
        if in_multiline_value {
            bracket_depth += bracket_delta(raw_line);
            if bracket_depth <= 0 {
                in_multiline_value = false;
                bracket_depth = 0;
            }
            continue;
        }
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') {
            if line.starts_with("[[") {
                return None;
            }
            let close = line.find(']')?;
            let table = line[1..close].trim().to_string();
            if !seen_tables.insert(table.clone()) {
                return None;
            }
            current_table = table;
            continue;
        }
        let eq = match find_unquoted_equals(raw_line) {
            Some(p) => p,
            None => continue,
        };
        let key = normalize_toml_key(&raw_line[..eq])?;
        let after = &raw_line[eq + 1..];
        let delta = bracket_delta(after);
        if delta > 0 {
            in_multiline_value = true;
            bracket_depth = delta;
            let id = (current_table.clone(), key.clone());
            if seen.contains_key(&id) {
                return None;
            }
            seen.insert(id, usize::MAX - i);
            continue;
        }
        if delta < 0 {
            return None;
        }
        let id = (current_table.clone(), key.clone());
        if let Some(&prev) = seen.get(&id) {
            if prev >= usize::MAX - lines.len() {
                return None;
            }
            let tolerant = if current_table.is_empty() {
                key != "clog" && key != "sections"
            } else if current_table == "clog" {
                !known_clog.contains(&key.as_str())
            } else if current_table == "sections" {
                true
            } else if current_table.starts_with("sections") {
                return None;
            } else {
                true
            };
            if !tolerant {
                return None;
            }
            delete[prev] = true;
            seen.insert(id, i);
        } else {
            seen.insert(id, i);
        }
    }
    if !delete.iter().any(|d| *d) {
        return None;
    }
    let mut cleaned = String::new();
    for (i, l) in lines.iter().enumerate() {
        if !delete[i] {
            cleaned.push_str(l);
            cleaned.push('\n');
        }
    }
    toml::from_str(&cleaned).ok()
}

fn find_unquoted_equals(line: &str) -> Option<usize> {
    let mut in_s = false;
    let mut in_d = false;
    let mut escaped = false;
    for (idx, ch) in line.char_indices() {
        if in_d {
            if escaped { escaped = false; continue; }
            if ch == '\\' { escaped = true; continue; }
            if ch == '"' { in_d = false; }
            continue;
        }
        if in_s {
            if ch == '\'' { in_s = false; }
            continue;
        }
        match ch {
            '"' => in_d = true,
            '\'' => in_s = true,
            '=' => return Some(idx),
            '#' => return None,
            _ => {}
        }
    }
    None
}

fn bracket_delta(s: &str) -> i32 {
    let mut depth = 0i32;
    let mut in_s = false;
    let mut in_d = false;
    let mut escaped = false;
    for ch in s.chars() {
        if in_d {
