            if ch == '\\' { escaped = true; continue; }
            if ch == '"' { in_d = false; }
            continue;
        }
        if in_s {
            if ch == '\'' { in_s = false; }
            continue;
        }
        match ch {
            '"' => in_d = true,
            '\'' => in_s = true,
            '[' | '{' => depth += 1,
            ']' | '}' => depth -= 1,
            '#' => break,
            _ => {}
        }
    }
    depth
}

